fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since both vectors have the same length, we can safely iterate by index.
    // For each index, compute bitwise OR of corresponding elements.
    let n = a.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        result.push(a[i] | b[i]);
    }

    result
}